SourceCode.Declaration:
/// <summary>
/// Class is used to make copy of <c>UPSVendPriceAdmTable</c> records. Should be called from form UPSVendPriceAdm.
/// </summary>
final class UPSVendPriceAdmTableCopy
{
    UPSVendPriceAdmTable        upsVendPriceAdmTableOrig;
    FormDataSource              upsVendPriceAdmTable_ds;

    #OCCRetryCount

}

Method.Source:
public void new(UPSVendPriceAdmTable _journalTable, FormDataSource _formDatasource = null)
{
    // Load vendor list price, or reference will change with form datasource.
    this.upsVendPriceAdmTableOrig   = UPSVendPriceAdmTable::find(_journalTable.JournalNum);
    this.upsVendPriceAdmTable_ds    = _formDatasource;
}

public static void main(Args _args)
{
    if (_args && _args.record() && _args.record().TableId == tableNum(UPSVendPriceAdmTable))
    {
        Object upsVendPriceAdmTable_ds = FormDataUtil::getFormDataSource(_args.record());
        UPSVendPriceAdmTableCopy upsVendPriceAdmTableCopy = new UPSVendPriceAdmTableCopy(_args.record(), upsVendPriceAdmTable_ds);

        upsVendPriceAdmTableCopy.run();
    }
    else
    {
        throw error(strFmt("@SYS27147", new DictClass(classNum(UPSVendPriceAdmTableCopy)).name()));
    }
}

private void run()
{
    UPSVendPriceAdmTable    upsVendPriceAdmTableNew;
    UPSVendPriceAdmTrans    upsVendPriceAdmTransNew, upsVendPriceAdmTransOrig;

    try
    {
        ttsbegin;

        upsVendPriceAdmTable_ds.create(true);
        upsVendPriceAdmTableNew = upsVendPriceAdmTable_ds.cursor();

        // Copy table
        upsVendPriceAdmTableNew.ExportCurrentPrice    = upsVendPriceAdmTableOrig.ExportCurrentPrice;
        upsVendPriceAdmTableNew.FromDate       = upsVendPriceAdmTableOrig.FromDate;
        upsVendPriceAdmTableNew.ToDate         = upsVendPriceAdmTableOrig.ToDate;
        upsVendPriceAdmTableNew.Status          = UPSDisabledEnabled::Disabled;

        upsVendPriceAdmTable_ds.write();

        // Copy line
        while select upsVendPriceAdmTransOrig
            where upsVendPriceAdmTransOrig.JournalNum == upsVendPriceAdmTableOrig.JournalNum
        {
            upsVendPriceAdmTransNew.clear();
            upsVendPriceAdmTransNew.initfromUPSVendPriceAdmTrans(upsVendPriceAdmTransOrig);
            upsVendPriceAdmTransNew.initFromUPSVendPriceAdmTable(upsVendPriceAdmTableNew);
            upsVendPriceAdmTransNew.insert();
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
